import{_ as l,o as i,c as e,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"精算（立替の精算）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/11-bill-reimbursement-guide.md","filePath":"v1/ja/guide/11-bill-reimbursement-guide.md"}'),t={name:"v1/ja/guide/11-bill-reimbursement-guide.md"};function o(h,a,n,d,u,s){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="精算-立替の精算" tabindex="-1">精算（立替の精算） <a class="header-anchor" href="#精算-立替の精算" aria-label="Permalink to &quot;精算（立替の精算）&quot;">​</a></h1><h2 id="_1-この機能について" tabindex="-1">1. この機能について <a class="header-anchor" href="#_1-この機能について" aria-label="Permalink to &quot;1. この機能について&quot;">​</a></h2><p>「精算」は、いったん自分で支払い（支出）を記録し、後から会社や相手から立替分を受け取るケース（例：出張、備品購入、立替払いなど）を管理するための機能です。</p><p>Koala での基本動作は次のとおりです。</p><ul><li>まず「支出」を記録し、「精算対象（報銷）」としてマークします</li><li>精算が完了したら、システムが自動で「精算入金」の収入明細を作成し、指定した口座に入金として反映します</li></ul><p>この方式のメリット：</p><ul><li>元の支出が残るため、用途を追跡しやすい</li><li>入金側も記録されるため、入金口座と日付を照合しやすい</li><li>集計が分かりやすい（支出と精算入金を別々に記録）</li></ul><h2 id="_2-こんなときに便利" tabindex="-1">2. こんなときに便利 <a class="header-anchor" href="#_2-こんなときに便利" aria-label="Permalink to &quot;2. こんなときに便利&quot;">​</a></h2><ul><li>会社の精算（交通費、宿泊費、食費、備品など）</li><li>立替後に相手から送金してもらうケース</li><li>後日回収する必要がある立替払い</li></ul><h2 id="_3-使い方" tabindex="-1">3. 使い方 <a class="header-anchor" href="#_3-使い方" aria-label="Permalink to &quot;3. 使い方&quot;">​</a></h2><h3 id="_3-1-精算対象の支出を作成する" tabindex="-1">3.1 精算対象の支出を作成する <a class="header-anchor" href="#_3-1-精算対象の支出を作成する" aria-label="Permalink to &quot;3.1 精算対象の支出を作成する&quot;">​</a></h3><ol><li>新規で支出明細を作成する</li><li>作成/編集画面で「精算（報銷）」（または「精算対象/精算待ち」などの類似オプション）をオンにする</li><li>保存後、一覧で「精算待ち/精算済み」などの状態が表示されます</li></ol><h3 id="_3-2-支出を精算する" tabindex="-1">3.2 支出を精算する <a class="header-anchor" href="#_3-2-支出を精算する" aria-label="Permalink to &quot;3.2 支出を精算する&quot;">​</a></h3><ol><li>明細一覧で「精算待ち」の支出を見つける</li><li>その明細を左にスワイプして「精算」を選ぶ</li><li>精算画面で設定する： <ul><li>金額：初期値は元の支出金額。必要に応じて実際の精算額に変更できます</li><li>日付：初期値は今日。必要に応じて実際の入金日へ変更します</li><li>入金口座：精算金が実際に入金された口座を選択します</li><li>メモ：任意</li></ul></li><li>「完了/保存」をタップ</li></ol><p>保存後、「精算入金」の収入明細が追加され、入金を記録できます。</p><h2 id="_4-ルールと注意点" tabindex="-1">4. ルールと注意点 <a class="header-anchor" href="#_4-ルールと注意点" aria-label="Permalink to &quot;4. ルールと注意点&quot;">​</a></h2><ul><li>「支出」かつ「精算対象」にマークされた明細のみ精算できます。</li><li>分割と精算は併用できません。分割済みの明細（子明細/分割コンテナを含む）は精算フローを開始できず、精算対象にした支出も分割できません。まず精算が必要かを決め、必要なら費用を先に分けたうえで、精算対象部分を別明細として作成してください。</li><li>「精算入金」が作成された支出は、通常は再度精算できません（重複入金を防ぐため）。</li><li>「精算入金」の収入明細を削除すると、元の支出は「精算待ち」に戻り、再度精算できます。</li><li>精算入金は収入として集計され、元の支出は支出として集計されます。資金の流れを明確にするためです。</li></ul><h2 id="_5-よくある質問" tabindex="-1">5. よくある質問 <a class="header-anchor" href="#_5-よくある質問" aria-label="Permalink to &quot;5. よくある質問&quot;">​</a></h2><h3 id="q1-精算と返金の違いは何ですか" tabindex="-1">Q1：精算と返金の違いは何ですか？ <a class="header-anchor" href="#q1-精算と返金の違いは何ですか" aria-label="Permalink to &quot;Q1：精算と返金の違いは何ですか？&quot;">​</a></h3><ul><li>返金：購入の取消/返金で元の明細影響を相殺する（負の金額の返金明細を追加）</li><li>精算：立替支出に対して後から入金を受け取る（精算入金の収入明細を追加）</li></ul><h3 id="q2-入金が別の口座に入った場合は" tabindex="-1">Q2：入金が別の口座に入った場合は？ <a class="header-anchor" href="#q2-入金が別の口座に入った場合は" aria-label="Permalink to &quot;Q2：入金が別の口座に入った場合は？&quot;">​</a></h3><p>精算画面で「入金口座」を実際の入金口座に変更してください。</p><h3 id="q3-一部だけ精算された場合は" tabindex="-1">Q3：一部だけ精算された場合は？ <a class="header-anchor" href="#q3-一部だけ精算された場合は" aria-label="Permalink to &quot;Q3：一部だけ精算された場合は？&quot;">​</a></h3><p>精算額を実際の精算額に変更してください。未精算分は元の支出側に残るため、後からの確認や追加精算に役立ちます。</p>',24)])])}const b=l(t,[["render",o]]);export{c as __pageData,b as default};
